import type { DiagramSource } from "./schema.ts";
import { collectTrace } from "./trace.ts";

const cell = (value: string) => value.replace(/\|/g, "\\|");

/**
 * Markdown table of task → diagram kinds → element labels (`diagrams/TRACEABILITY.md`).
 * `taskIds` is the ordered task list from tasks.md, or null for sources without tasks.
 */
export function renderTraceability(
	source: DiagramSource,
	taskIds: readonly string[] | null,
): string {
	const lines = [
		`# Traceability: ${source.feature}`,
		"",
		"Generated by `rg-diagrams` from `diagram.yaml`. Do not edit.",
		"",
	];
	const trace = collectTrace(source);
	const ids = taskIds ?? [...trace.keys()];
	if (ids.length === 0) {
		lines.push("No task references.");
		return `${lines.join("\n")}\n`;
	}
	lines.push("| Task | Diagrams | Elements |", "|------|----------|----------|");
	for (const id of ids) {
		const refs = trace.get(id);
		if (!refs) {
			lines.push(`| ${id} | — | — (untraced) |`);
			continue;
		}
		const kinds = [...new Set(refs.map((r) => r.kind))].join(", ");
		const elements = [...new Set(refs.map((r) => cell(r.element)))].join("; ");
		lines.push(`| ${id} | ${kinds} | ${elements} |`);
	}
	return `${lines.join("\n")}\n`;
}
